 document.querySelectorAll('[data-act]').forEach(b=>b.addEventListener('click',()=>{let a=b.dataset.act;if(a==='interact'){if(mode==='intro')window.startCase();else interact()}if(a==='journal')openJournal();if(a==='back'&&mode==='accuse')window.backToGame()}));

